settings.custom_css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

.rcl-widget {
  background: transparent;
  display: flex;
  flex-direction: row;
  align-items: stretch;
  gap: 24px;
  width: 100%;
  max-width: 1400px;
  box-sizing: border-box;
}

.rcl-image-col {
  flex: 0 0 42%;
  background: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 30px;
  min-height: 420px;
  border-radius: 12px;
  /*box-shadow: 0px 20px 40px 0px #0F1D280F;*/
  box-sizing: border-box;
}

.rcl-image-col img {
  width: 100%;
  max-width: 340px;
  height: auto;
  object-fit: contain;
  transition: opacity 0.35s ease;
  display: block;
}

.rcl-tabs-col {
  flex: 1 1 58%;
  padding: 44px 48px 44px 40px;
  display: flex;
  flex-direction: column;
  gap: 0;
  box-sizing: border-box;
}

.rcl-cat-tabs {
  display: flex;
  gap: 0;
  border-bottom: 1.5px solid #d9dde3;
  margin-bottom: 20px;
}

.rcl-cat-tab {
  background: none;
  border: none;
  outline: none;
  cursor: pointer;
  font-size: 15px;
  font-weight: 500;
  color: #333333;
  padding: 10px 28px 10px 0;
  position: relative;
  transition: color 0.2s;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

.rcl-cat-tab:first-child { padding-left: 0; }

.rcl-cat-tab::after {
  content: '';
  position: absolute;
  bottom: -1.5px;
  left: 0;
  right: 18px;
  height: 2px;
  background: #005287;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.25s ease;
}
.rcl-cat-tab:hover {
  background: #fff;
  color: #005287;
}
.rcl-cat-tab.active {
  background: #FFF;
  color: #005287;
  font-weight: 700;
}

.rcl-cat-tab.active::after {
  transform: scaleX(1);
}

.rcl-prod-tabs {
  display: none;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 24px;
}

.rcl-prod-tabs.active { display: flex; }

.rcl-prod-tab {
  background: #FFFFFF;
  border: 1.5px solid rgba(0, 82, 135, 0.2);
  border-radius: 6px;
  outline: none;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  color: #333333;
  padding: 8px 20px;
  transition: background 0.2s, color 0.2s, border-color 0.2s;
  letter-spacing: 0.01em;
}

.rcl-prod-tab:hover {
  border-color: #005287;
  color: #FFF;
  background-color: #005287 !important;
}

.rcl-prod-tab.active {
  background: #005287;
  border-color: #005287;
  color: #FFFFFF;
}

.rcl-panel {
  display: none;
  flex-direction: column;
  gap: 6px;
  animation: rclFadeIn 0.25s ease;
}

.rcl-panel.active { display: flex; }

@keyframes rclFadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 1; transform: translateY(0); }
}


.rcl-product-name {
  font-size: 40px;
  font-weight: 800;
  color: #00223D!important;
  line-height: 1.1;
  margin: 0 0 10px;
}

.rcl-product-desc {
  font-size: 14.5px;
  color: #666666;
  line-height: 1.65;
  margin: 0 0 14px;
}

.rcl-advantages-title {
  font-size: 15px;
  font-weight: 700;
  color: #00223D;
  margin: 0 0 8px;
}

.rcl-advantages-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.rcl-advantages-list li {
  font-size: 14px;
  color: #666666;
  padding-left: 18px;
  position: relative;
  line-height: 1.55;
}

.rcl-advantages-list li::before {
  content: '•';
  position: absolute;
  left: 0;
  color: #666666;
}

@media (max-width: 768px) {
  .rcl-widget        { flex-direction: column; gap: 16px; }
  .rcl-image-col     { flex: none; min-height: 260px; padding: 28px 20px; }
  .rcl-tabs-col      { padding: 28px 20px; }
  .rcl-product-name  { font-size: 28px; }
  .rcl-cat-tab       { font-size: 13.5px; padding: 8px 16px 8px 0; }
}
